void _productCollectionSerialize(
  ProductCollection object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeLong(offsets[0], object.ageRestriction);
  writer.writeString(offsets[1], object.aisleLocation);
  writer.writeStringList(offsets[2], object.allergens);
  writer.writeBool(offsets[3], object.allowRoomFolio);
  writer.writeString(offsets[4], object.apparelCategory);
  writer.writeString(offsets[5], object.artisanLabel);
  writer.writeDateTime(offsets[6], object.bakeTimestamp);
  writer.writeString(offsets[7], object.bakeryType);
  writer.writeString(offsets[8], object.barcode);
  writer.writeString(offsets[9], object.baseNotes);
  writer.writeDouble(offsets[10], object.basePrice);
  writer.writeObjectList<BatchEmbed>(
    offsets[11],
    allOffsets,
    BatchEmbedSchema.serialize,
    object.batches,
  );
  writer.writeString(offsets[12], object.brandId);
  writer.writeString(offsets[13], object.brandRange);
  writer.writeString(offsets[14], object.businessCategory);
  writer.writeString(offsets[15], object.businessType);
  writer.writeString(offsets[16], object.cafeCategory);
  writer.writeDouble(offsets[17], object.calories);
